var Regs = [/book_id=(\d+)/i, /query=(\d+)/, /d=(\d{19})/i, /(\d{19})/i];
var book_id = "";
for (let Reg of Regs) {
    let mat = baseUrl.match(Reg);
    if (mat) {
        book_id = mat[1];
        break;
    }
}

if (!book_id) throw new Error("没有 book_id !")

result = java.ajax(xGorgon(
     "detail",
     "book_id=" + book_id,
     null,
     "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
))

try {
