    "/reading/bookapi/read_history/update/v/?", "",
    gzip(JSON.stringify({
      update_datas: [{
        book_id: book_id,
        read_timestamp_ms: Date.now()
      }]
    }).replace(/\"(\d+)\"/g, "$1")), "sessionid=" + (String(cookie.getKey("fanqienovel.com", "sessionid")) ? String(cookie.getKey("fanqienovel.com", "sessionid")) : source.getLoginInfoMap()['手动登录Token'])
)} catch (e) {
