try{
var lalalala = java.getElements(".audio-iframe").attr("data-info").substring(0,5);
}catch(err){
var lalalala = String('FRDSHFSKV').substring(0,5);
}

code = java.get("code");
no = java.get("no");
time = (new Date).getTime();

U = lalalala + "FSKVKSKFKS";
sign = java.md5Encode(time + code + no + U);

url = `http://www.tingshu168.com/web/index/video_new?code=${code}&no=${no}&type=0&timestamp=${time}&sign=${sign}`;

try{
	h = java.ajax(url);
	if(JSON.parse(h).code==201){
		java.toast("资源已下架！")
		}
	else{
    u = JSON.parse(h).data.videoUrl;
    videoUrl = `${u},{"headers":{"Referer":"http://www.tingshu168.com/"}}`;
   }
}catch(err){
	java.toast("解析错误！")
	}

