  ].join("&")`

obj = (title, url, type, type1) => ({
  title: title,
  url: url,
  style: {
    layout_flexGrow: 1,
    layout_flexBasisPercent: type
  }
})

arr = []
java.longToast("请稍等，发现列表正在热更新！")
index=[0, 1, 2]
for (let i of index) {
  // java.toast(i)
  let type = i
  $ = JSON.parse(java.ajax(source.bookSourceUrl + "/reading/bookapi/new_category/front/v/?" + [
      "update_version_code=58932",
      "distinct_style=1",
      "new_category_tab=" + i
    ].join("&")
  )).data.category_tab_data
  cate = []
  cate.push(obj(
    "====== " + $.tab_name + " ======", "", 1
  ))
  $.cell_data.forEach((c) => {
    gender_1 = (type == 0 || type == 1) ? type : 1;
    genre_1 = type == 3 ? 1 : type == 5 ? 110 : type == 6 ? 130 : 0;
    cate.push(obj(
      c.cell_name,
      js(c.atom_data[0].category_data.category_id, genre_1, gender_1),
      1
    ))
    for (j = 2; j < 5; j++) {
      c.atom_data.slice(1).forEach((a) => {
        d = a.category_data
        if (d.name.length == j) {
          cate.push(obj(d.name, js(d.category_id, genre_1, gender_1), -1))
        }
      })
    }
  })
  arr = cate.concat(arr)
}

